class LmdbMappedOperatorLearningContextTest {

	@TempDir
	Path temporary;

	@Test
	void contextualFilterDoesNotReplaceWholePrefixWithOneInvocationFact() {
		assertContextualFilter(false);
	}

	@Test
	void contextualNestedFilterDoesNotReplaceWholePrefixWithOneInvocationFact() {
		assertContextualFilter(true);
	}

	private void assertContextualFilter(boolean nested) {
		var values = SimpleValueFactory.getInstance();
		StatementPattern prefix = new StatementPattern(Var.of("s"),
				Var.of("prefixPredicate", values.createIRI("urn:test:prefix")), Var.of("p"));
		Filter filter = new Filter(new StatementPattern(Var.of("s"),
				Var.of("filterPredicate", values.createIRI("urn:test:filter")), Var.of("o")),
				new ValueConstant(values.createLiteral(true)));
		if (nested) {
			filter = new Filter(filter, new ValueConstant(values.createLiteral(true)));
		}
		var call = PackedCostTestSupport.disconnectedFilter(prefix, filter, 100_000.0d);
		PackedCostEstimate output = estimate();
		new LmdbMappedFrontierLearningSession(runtimeWithFact(call.query(), call.factorRelationId()), call.query(),
				true)
						.applyOperator(call.factorRelationId(), new int[] { call.factorRelationId() }, call.context(),
								output);

		assertEquals(100_000.0d, output.outputRows(), 0.0d,
				"a per-invocation logical fact cannot replace the complete inherited join-prefix cardinality");
		assertNotNull(output.runtimeFeedbackContract(), "physical feedback must remain available");
	}

	@Test
	void independentFilterStillUsesItsExactLogicalFact() {
		var values = SimpleValueFactory.getInstance();
		var call = PackedCostTestSupport.filterOperator(new Filter(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				new ValueConstant(values.createLiteral(true))), 100_000.0d);
		PackedCostEstimate output = estimate();
		new LmdbMappedFrontierLearningSession(runtimeWithFact(call.query(), call.operatorRelationId()), call.query(),
				true)
						.applyOperator(call.operatorRelationId(), new int[] { call.operatorRelationId() },
								call.context(),
								output);
		assertEquals(1.0d, output.outputRows(), 0.0d);
		assertEquals(EvidenceGuarantee.DATABASE_EXACT, output.evidenceGuarantee());
	}

	private LmdbEstimatorRuntime runtimeWithFact(PackedQueryView query, int relationId) {
		LmdbEstimatorRuntime runtime = mock(LmdbEstimatorRuntime.class);
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(temporary.resolve("estimator"));
		// Train the independent logical fact through the real publication boundary. Spying on this class
		// instruments every later instance in the JVM and contaminates allocation-contract tests.
		PackedCostEstimate independent = estimate();
		new LmdbMappedFrontierLearningSession(runtime, query, true).applyOperator(relationId,
				new int[] { relationId }, PackedCostTestSupport.prefixContext(new int[0], 0, 1.0d, 0), independent);
		var contract = independent.runtimeFeedbackContract();
		assertNotNull(contract);
		RuntimeFeedbackTarget target = feedback.resolveRuntimeFeedbackTarget(contract);
		target.open();
		target.close(1L, 1.0d, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);
		target.recordActualPhysicalImplementation(contract.physicalImplementationId());
		feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		when(runtime.feedback()).thenReturn(feedback);
		return runtime;
	}

	private static PackedCostEstimate estimate() {
		PackedCostEstimate output = new PackedCostEstimate();
		output.setContextualRows(100_000.0d, 100_000.0d);
		output.setEvidenceGuarantee(EvidenceGuarantee.SCALAR_FALLBACK);
		return output;
	}
}
